package com.gymflow.app;
import android.content.Intent; import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity;
public class LoginActivity extends AppCompatActivity {
 @Override protected void onCreate(Bundle b){super.onCreate(b);if(Session.logged(this)){startActivity(new Intent(this,MainActivity.class));finish();return;}LinearLayout r=Ui.page(this);Space sp=new Space(this);r.addView(sp,new LinearLayout.LayoutParams(1,Ui.dp(this,36)));r.addView(Ui.title(this,"GymFlow"));r.addView(Ui.subtitle(this,"Gestioná, entrená y hacé crecer tu gimnasio."));EditText email=Ui.input(this,"Email");email.setInputType(android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);r.addView(email);EditText pass=Ui.input(this,"Contraseña");pass.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);r.addView(pass);Button login=Ui.button(this,"Iniciar sesión");r.addView(login);Button register=Ui.button(this,"Crear cuenta de gimnasio");r.addView(register);TextView state=Ui.subtitle(this,"Datos protegidos y separados por gimnasio con Supabase.");r.addView(state);login.setOnClickListener(v->{String e=email.getText().toString().trim(),p=pass.getText().toString();if(e.isEmpty()||p.isEmpty()){Toast.makeText(this,"Completá email y contraseña",Toast.LENGTH_SHORT).show();return;}login.setEnabled(false);state.setText("Ingresando...");Cloud.signIn(this,e,p,(code,body)->{login.setEnabled(true);if(code>=200&&code<300){startActivity(new Intent(this,MainActivity.class));finish();}else state.setText("No se pudo ingresar: "+Cloud.err(body));});});register.setOnClickListener(v->startActivity(new Intent(this,RegisterActivity.class)));setContentView(r);}
}
